CREATE OR REPLACE FUNCTION public.yorisou_line_subject_state(p_line_subject_hash text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'subject_hash', p_line_subject_hash,
    'state', coalesce((select s.state from public.yorisou_canonical_line_subjects s
                        where s.line_subject_hash = p_line_subject_hash), 'unknown'),
    'owner_fingerprint', (select s.owner_fingerprint from public.yorisou_canonical_line_subjects s
                           where s.line_subject_hash = p_line_subject_hash),
    'erased_at', (select s.erased_at from public.yorisou_canonical_line_subjects s
                   where s.line_subject_hash = p_line_subject_hash)
  );
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_line_subject_state(p_line_subject_hash text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_line_subject_state(p_line_subject_hash text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_line_subject_state(p_line_subject_hash text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_line_subject_state(p_line_subject_hash text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_line_subject_lock(p_line_subject_hash text, p_owner_fingerprint text DEFAULT NULL::text)
 RETURNS yorisou_canonical_line_subjects
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_subject public.yorisou_canonical_line_subjects%rowtype;
begin
  if p_line_subject_hash is null or p_line_subject_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'line_subject_hash_must_be_sha256_hex';
  end if;

  for i in 1..2 loop
    select * into v_subject
      from public.yorisou_canonical_line_subjects
     where line_subject_hash = p_line_subject_hash
       for update;
    if found then
      return v_subject;
    end if;

    begin
      insert into public.yorisou_canonical_line_subjects (line_subject_hash, owner_fingerprint)
      values (p_line_subject_hash, p_owner_fingerprint);
    exception when unique_violation then
      -- A concurrent inserter won. Loop once more; the select will now find and LOCK its row, which
      -- is what makes the two callers serial instead of both proceeding on an unlocked subject.
      null;
    end;
  end loop;

  select * into v_subject
    from public.yorisou_canonical_line_subjects
   where line_subject_hash = p_line_subject_hash
     for update;
  if not found then
    raise exception 'line_subject_state_unavailable';
  end if;
  return v_subject;
end $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_line_subject_lock(p_line_subject_hash text, p_owner_fingerprint text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_line_subject_lock(p_line_subject_hash text, p_owner_fingerprint text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_line_subject_lock(p_line_subject_hash text, p_owner_fingerprint text) from authenticated';
  end if;
  -- deliberately NOT granted to service_role: an internal lock helper, not an entry point.
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_line_subject_erasure_residue(p_line_subject_hash text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select (
    (select count(*)::int
       from public.yorisou_canonical_line_events
      where line_subject_hash = p_line_subject_hash and retention_state = 'active')
    +
    (select case when exists (
        select 1 from public.yorisou_canonical_line_subjects
         where line_subject_hash = p_line_subject_hash and state = 'erased')
      then 0 else 1 end)
  );
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_line_subject_erasure_residue(p_line_subject_hash text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_line_subject_erasure_residue(p_line_subject_hash text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_line_subject_erasure_residue(p_line_subject_hash text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_line_subject_erasure_residue(p_line_subject_hash text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_line_subject_erase(p_line_subject_hash text, p_owner_fingerprint text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_subject   public.yorisou_canonical_line_subjects%rowtype;
  v_erased    int;
  v_residue   int;
  v_already   boolean;
begin
  v_subject := public.yorisou_line_subject_lock(p_line_subject_hash, p_owner_fingerprint);
  v_already := v_subject.state = 'erased';

  update public.yorisou_canonical_line_subjects
     set state             = 'erased',
         erased_at         = coalesce(erased_at, now()),
         owner_fingerprint = coalesce(p_owner_fingerprint, owner_fingerprint),
         updated_at        = now()
   where line_subject_hash = p_line_subject_hash;

  update public.yorisou_canonical_line_events
     set retention_state   = 'erased',
         erased_at         = now(),
         message_text      = null,
         postback_data     = null,
         reply_error       = null,
         owner_account_id  = null,
         line_subject_id   = null,
         owner_fingerprint = coalesce(p_owner_fingerprint, owner_fingerprint),
         updated_at        = now()
   where line_subject_hash = p_line_subject_hash
     and retention_state = 'active';

  get diagnostics v_erased = row_count;

  select count(*)::int into v_residue
    from public.yorisou_canonical_line_events
   where line_subject_hash = p_line_subject_hash
     and retention_state = 'active';

  if v_residue <> 0 then
    -- Unreachable under the subject lock; asserted because a deletion that reports success over
    -- residue is the one failure mode this whole family exists to prevent.
    raise exception 'line_subject_erasure_residue';
  end if;

  return jsonb_build_object(
    'subject_state', 'erased',
    'events_erased', v_erased,
    'active_residue', 0,
    'already_erased', v_already
  );
end $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_line_subject_erase(p_line_subject_hash text, p_owner_fingerprint text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_line_subject_erase(p_line_subject_hash text, p_owner_fingerprint text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_line_subject_erase(p_line_subject_hash text, p_owner_fingerprint text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_line_subject_erase(p_line_subject_hash text, p_owner_fingerprint text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_line_recent_subjects(p_limit integer DEFAULT 10)
 RETURNS SETOF yorisou_canonical_line_events
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from (
    select distinct on (line_subject_hash) *
      from public.yorisou_canonical_line_events
     where retention_state = 'active'
     order by line_subject_hash, received_at desc, line_event_id desc
  ) latest
  order by received_at desc, line_event_id desc
  limit greatest(1, coalesce(p_limit, 10));
$function$;

