    execute 'revoke all on function public.yorisou_line_events_for_owner(p_owner_fingerprint text, p_limit integer) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_line_events_for_owner(p_owner_fingerprint text, p_limit integer) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_line_event_record(p_line_event_id text, p_line_subject_hash text, p_event_type text, p_line_subject_id text DEFAULT NULL::text, p_webhook_event_id text DEFAULT NULL::text, p_owner_account_id text DEFAULT NULL::text, p_owner_fingerprint text DEFAULT NULL::text, p_source_type text DEFAULT NULL::text, p_message_type text DEFAULT NULL::text, p_message_text text DEFAULT NULL::text, p_postback_data text DEFAULT NULL::text, p_delivery_mode text DEFAULT NULL::text, p_is_redelivery boolean DEFAULT false, p_reply_token_present boolean DEFAULT false, p_reply_status text DEFAULT 'not_attempted'::text, p_reply_error text DEFAULT NULL::text, p_event_timestamp timestamp with time zone DEFAULT NULL::timestamp with time zone, p_received_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_subject  public.yorisou_canonical_line_subjects%rowtype;
  v_existing public.yorisou_canonical_line_events%rowtype;
  v_received timestamptz := coalesce(p_received_at, now());
begin
  if p_line_event_id is null or length(trim(p_line_event_id)) = 0 then
    raise exception 'line_event_id_required';
  end if;
  if p_line_subject_hash is null or p_line_subject_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'line_subject_hash_must_be_sha256_hex';
  end if;

  -- THE BARRIER. Locking the subject before touching any event row is what serializes a brand-new
  -- event id against a completed erasure. Without it the two transactions never contend, because
  -- they address different rows, and both succeed.
  v_subject := public.yorisou_line_subject_lock(p_line_subject_hash, p_owner_fingerprint);

  if v_subject.state = 'erased' then
    -- Absorbed. No row, no raw subject id, no message text, no postback data, no reply error.
    return jsonb_build_object('outcome', 'erased', 'line_event_id', p_line_event_id);
  end if;

  select * into v_existing
    from public.yorisou_canonical_line_events
   where line_event_id = p_line_event_id
     for update;

  if not found and p_webhook_event_id is not null then
    select * into v_existing
      from public.yorisou_canonical_line_events
     where webhook_event_id = p_webhook_event_id
       for update;
  end if;

  if found then
    if v_existing.line_subject_hash is distinct from p_line_subject_hash then
      raise exception 'line_event_identity_conflict';
    end if;

    if v_existing.retention_state = 'erased' then
      return jsonb_build_object('outcome', 'erased', 'line_event_id', v_existing.line_event_id);
    end if;

    update public.yorisou_canonical_line_events
       set reply_status        = coalesce(p_reply_status, reply_status),
           reply_error         = p_reply_error,
           reply_token_present = coalesce(p_reply_token_present, reply_token_present),
           message_text        = coalesce(p_message_text, message_text),
           is_redelivery       = is_redelivery or coalesce(p_is_redelivery, false),
           owner_account_id    = coalesce(p_owner_account_id, owner_account_id),
           owner_fingerprint   = coalesce(p_owner_fingerprint, owner_fingerprint),
           line_subject_id     = coalesce(p_line_subject_id, line_subject_id),
           updated_at          = now()
     where line_event_id = v_existing.line_event_id;

    if p_owner_fingerprint is not null and v_subject.owner_fingerprint is distinct from p_owner_fingerprint then
      update public.yorisou_canonical_line_subjects
         set owner_fingerprint = p_owner_fingerprint, updated_at = now()
       where line_subject_hash = p_line_subject_hash;
    end if;

    return jsonb_build_object('outcome', 'repeated', 'line_event_id', v_existing.line_event_id);
  end if;

  -- The handler is scoped to the INSERT alone rather than to the whole function. A plpgsql exception
  -- block is a subtransaction, and rolling the whole body back would also roll back the subject row
  -- this transaction may have just created — discarding the barrier's state to report a duplicate.
  begin
    insert into public.yorisou_canonical_line_events (
      line_event_id, webhook_event_id, line_subject_hash, line_subject_id, owner_account_id, owner_fingerprint,
      source_type, event_type, message_type, message_text, postback_data, delivery_mode,
      is_redelivery, reply_token_present, reply_status, reply_error, event_timestamp, received_at
    ) values (
      p_line_event_id, p_webhook_event_id, p_line_subject_hash, p_line_subject_id, p_owner_account_id, p_owner_fingerprint,
      p_source_type, p_event_type, p_message_type, p_message_text, p_postback_data, p_delivery_mode,
      coalesce(p_is_redelivery, false), coalesce(p_reply_token_present, false),
      coalesce(p_reply_status, 'not_attempted'), p_reply_error, p_event_timestamp, v_received
    );
  exception
    when unique_violation then
      -- Lost the insert race on `webhook_event_id`. The winner wrote the same event, so this is a
      -- repeat, not a failure — but only if it is genuinely the same subject.
      if exists (
        select 1 from public.yorisou_canonical_line_events
         where webhook_event_id = p_webhook_event_id
           and line_subject_hash is distinct from p_line_subject_hash
      ) then
        raise exception 'line_event_identity_conflict';
      end if;
      return jsonb_build_object('outcome', 'repeated', 'line_event_id', p_line_event_id);
  end;

  if p_owner_fingerprint is not null and v_subject.owner_fingerprint is distinct from p_owner_fingerprint then
    update public.yorisou_canonical_line_subjects
       set owner_fingerprint = p_owner_fingerprint, updated_at = now()
     where line_subject_hash = p_line_subject_hash;
  end if;

  return jsonb_build_object('outcome', 'recorded', 'line_event_id', p_line_event_id);
end $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_line_event_record(p_line_event_id text, p_line_subject_hash text, p_event_type text, p_line_subject_id text, p_webhook_event_id text, p_owner_account_id text, p_owner_fingerprint text, p_source_type text, p_message_type text, p_message_text text, p_postback_data text, p_delivery_mode text, p_is_redelivery boolean, p_reply_token_present boolean, p_reply_status text, p_reply_error text, p_event_timestamp timestamp with time zone, p_received_at timestamp with time zone) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_line_event_record(p_line_event_id text, p_line_subject_hash text, p_event_type text, p_line_subject_id text, p_webhook_event_id text, p_owner_account_id text, p_owner_fingerprint text, p_source_type text, p_message_type text, p_message_text text, p_postback_data text, p_delivery_mode text, p_is_redelivery boolean, p_reply_token_present boolean, p_reply_status text, p_reply_error text, p_event_timestamp timestamp with time zone, p_received_at timestamp with time zone) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_line_event_record(p_line_event_id text, p_line_subject_hash text, p_event_type text, p_line_subject_id text, p_webhook_event_id text, p_owner_account_id text, p_owner_fingerprint text, p_source_type text, p_message_type text, p_message_text text, p_postback_data text, p_delivery_mode text, p_is_redelivery boolean, p_reply_token_present boolean, p_reply_status text, p_reply_error text, p_event_timestamp timestamp with time zone, p_received_at timestamp with time zone) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_line_event_record(p_line_event_id text, p_line_subject_hash text, p_event_type text, p_line_subject_id text, p_webhook_event_id text, p_owner_account_id text, p_owner_fingerprint text, p_source_type text, p_message_type text, p_message_text text, p_postback_data text, p_delivery_mode text, p_is_redelivery boolean, p_reply_token_present boolean, p_reply_status text, p_reply_error text, p_event_timestamp timestamp with time zone, p_received_at timestamp with time zone) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_line_activity_residue(p_line_subject_hash text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::int from public.yorisou_canonical_line_events
   where line_subject_hash = p_line_subject_hash and retention_state = 'active';
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_line_activity_residue(p_line_subject_hash text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_line_activity_residue(p_line_subject_hash text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_line_activity_residue(p_line_subject_hash text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_line_activity_residue(p_line_subject_hash text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_line_activity_inventory(p_line_subject_hash text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'subject_hash', p_line_subject_hash,
    'subject_state', coalesce((select s.state from public.yorisou_canonical_line_subjects s
                                where s.line_subject_hash = p_line_subject_hash), 'unknown'),
    'owner_fingerprint', (select s.owner_fingerprint from public.yorisou_canonical_line_subjects s
                           where s.line_subject_hash = p_line_subject_hash),
    'active_events', (select count(*)::int from public.yorisou_canonical_line_events e
                       where e.line_subject_hash = p_line_subject_hash and e.retention_state = 'active'),
    'erased_events', (select count(*)::int from public.yorisou_canonical_line_events e
                       where e.line_subject_hash = p_line_subject_hash and e.retention_state = 'erased'),
    'latest_received_at', (select max(e.received_at) from public.yorisou_canonical_line_events e
                            where e.line_subject_hash = p_line_subject_hash and e.retention_state = 'active')
  );
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_line_activity_inventory(p_line_subject_hash text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_line_activity_inventory(p_line_subject_hash text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_line_activity_inventory(p_line_subject_hash text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_line_activity_inventory(p_line_subject_hash text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_line_activity_erase(p_line_subject_hash text, p_owner_fingerprint text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_result jsonb;
begin
  v_result := public.yorisou_line_subject_erase(p_line_subject_hash, p_owner_fingerprint);
  return (v_result ->> 'events_erased')::int;
end $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_line_activity_erase(p_line_subject_hash text, p_owner_fingerprint text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_line_activity_erase(p_line_subject_hash text, p_owner_fingerprint text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_line_activity_erase(p_line_subject_hash text, p_owner_fingerprint text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_line_activity_erase(p_line_subject_hash text, p_owner_fingerprint text) to service_role';
  end if;
end $$;
